'use client'
import { cn, useSignal, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { forwardRef } from 'react'
import type { ButtonHTMLAttributes } from 'react'
import styles from './copy-button.module.css'

export interface CopyButtonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'value'> {
  /** The text written to the clipboard on click. */
  value: string
  size?: 'sm' | 'md'
  labels?: { copy?: string; copied?: string }
}

/**
 * `forwardRef` so `ref` reaches the underlying `<button>` — and so it is TYPED. See
 * `textarea.tsx` for the full rationale (2026-07-28 report C10). Enforced by
 * `ref-parity.test.ts`, which found this component: the plan's own list of 16 was itself
 * incomplete, which is why the rule is a guard and not a checklist.
 */
export const CopyButton = forwardRef<HTMLButtonElement, CopyButtonProps>(function CopyButton(
  { value, size = 'md', labels, className, ...props },
  ref,
) {
  useSignals()
  const copied = useSignal(false)
  const copyLabel = labels?.copy ?? t(builtin.copyButton.copy)
  const copiedLabel = labels?.copied ?? t(builtin.copyButton.copied)

  const handleClick = () => {
    void navigator.clipboard.writeText(value)
    copied.value = true
    setTimeout(() => {
      copied.value = false
    }, 2000)
  }

  return (
    <button
      type="button"
      aria-label={copied.value ? copiedLabel : copyLabel}
      data-state={copied.value ? 'copied' : 'idle'}
      data-size={size}
      className={cn(styles['copyButton'], className as string | undefined)}
      onClick={handleClick}
      ref={ref as never}
      {...props}
    >
      {copied.value ? (
        <svg aria-hidden="true" viewBox="0 0 16 16" className={styles['icon']}>
          <path
            d="M13.5 4.5 6 12 2.5 8.5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      ) : (
        <svg aria-hidden="true" viewBox="0 0 16 16" className={styles['icon']}>
          <rect
            x="5.5"
            y="5.5"
            width="8"
            height="8"
            rx="1.5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
          />
          <path
            d="M3.5 10.5h-1a1 1 0 0 1-1-1v-7a1 1 0 0 1 1-1h7a1 1 0 0 1 1 1v1"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
          />
        </svg>
      )}
    </button>
  )
})

@layer cascivo.component {
  .copyButton {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background-color: var(--cascivo-color-surface);
    color: var(--cascivo-color-text-subtle);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-control);
    cursor: pointer;
    transition:
      color var(--cascivo-duration-150) var(--cascivo-ease-out),
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover {
      background-color: var(--cascivo-color-bg-subtle);
      color: var(--cascivo-color-text);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    &[data-state='copied'] {
      color: var(--cascivo-color-success);
    }

    &[data-size='sm'] {
      inline-size: var(--cascivo-control-height-sm);
      block-size: var(--cascivo-control-height-sm);
    }

    &[data-size='md'] {
      inline-size: var(--cascivo-control-height-md);
      block-size: var(--cascivo-control-height-md);
    }
  }

  .icon {
    inline-size: 1rem;
    block-size: 1rem;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'CopyButton',
  description: 'Icon button that copies a value to the clipboard with copied feedback',
  category: 'inputs',
  // Writing to the clipboard is its only job, and that is a browser API.
  clientJs: 'required',
  states: ['idle', 'copied'],
  variants: [],
  sizes: ['sm', 'md'],
  props: [
    {
      name: 'value',
      type: 'string',
      required: true,
      description: 'The text written to the clipboard on click',
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md'",
      required: false,
      default: 'md',
    },
    {
      name: 'labels',
      type: '{ copy?: string; copied?: string }',
      required: false,
      description: 'Overrides the built-in i18n labels per instance',
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-text-subtle',
    '--cascivo-color-text',
    '--cascivo-color-border',
    '--cascivo-color-bg-subtle',
    '--cascivo-color-success',
    '--cascivo-radius-control',
    '--cascivo-focus-ring',
    '--cascivo-control-height-sm',
    '--cascivo-control-height-md',
  ],
  accessibility: {
    role: 'button',
    wcag: '2.2-AA',
    keyboard: ['Enter', 'Space'],
  },
  examples: [
    { title: 'Default', code: '<CopyButton value="npx cascivo add button" />' },
    { title: 'Small', code: '<CopyButton value="pnpm install" size="sm" />' },
    {
      title: 'Custom labels',
      code: "<CopyButton value=\"token\" labels={{ copy: 'Copy token', copied: 'Token copied' }} />",
      description: 'Override the built-in copy/copied strings per instance',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['clipboard', 'copy', 'button', 'snippet'],
  intent: {
    whenToUse: [
      'Letting users copy a short value to the clipboard — install commands, API keys, tokens, share links',
      'Inline next to code snippets or read-only fields where copying is the primary affordance',
    ],
    whenNotToUse: [
      'Triggering a general action — use Button',
      'Copying content the user can already select and edit freely where a copy affordance adds nothing',
    ],
    antiPatterns: [
      {
        bad: 'Wiring CopyButton to perform a non-clipboard action via onClick',
        good: 'Use Button for arbitrary actions; CopyButton always writes value to the clipboard',
        why: 'Its click handler is fixed to navigator.clipboard.writeText(value) plus copied feedback — overloading it breaks user expectation',
      },
    ],
    related: [
      {
        name: 'Button',
        relationship: 'alternative',
        reason: 'Use for actions other than copying to clipboard',
      },
      {
        name: 'Input',
        relationship: 'pairs-with',
        reason: 'Often placed alongside a read-only field whose value it copies',
      },
    ],
    a11yRationale:
      'Renders a native <button> so Enter/Space, focus, and role come from the platform; the aria-label swaps between copy and copied labels to announce the state change to screen readers since the icon swap alone is silent, and the SVG icons are aria-hidden',
    content: {
      tone: 'Concise action/confirmation labels',
      notes:
        'Default copy/copied strings come from the i18n catalog; override per instance via labels (e.g. "Copy token" / "Token copied")',
    },
    flexibility: [
      {
        area: 'labels',
        level: 'flexible',
        note: 'copy/copied strings overridable via labels; default from i18n catalog',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Styling resolves to semantic --cascivo-color-* tokens; copied state uses --cascivo-color-success',
      },
    ],
  },
}
